/**
 * TableOfContentsClient
 *
 * Utility for working with SkyCMS TOC JSON documents generated by PublishingService.WriteTocAsync.
 * Supports parsing, validation, item lookup, sorting, paging, and URL construction.
 */
class TableOfContentsClient {
  constructor(document) {
    this.document = this.normalizeDocument(document || {});
  }

  static fromObject(document) {
    return new TableOfContentsClient(document);
  }

  static fromJson(jsonText) {
    if (typeof jsonText !== 'string' || jsonText.trim().length === 0) {
      throw new Error('TOC JSON must be a non-empty string.');
    }

    return new TableOfContentsClient(JSON.parse(jsonText));
  }

  static async fromUrl(url, fetchImpl = fetch) {
    if (!url) {
      throw new Error('TOC URL is required.');
    }

    const response = await fetchImpl(url, {
      method: 'GET',
      headers: { Accept: 'application/json, text/plain, */*' }
    });

    if (!response.ok) {
      throw new Error(`Failed to fetch TOC from ${url}: HTTP ${response.status}`);
    }

    const data = await response.json();
    return new TableOfContentsClient(data);
  }

  normalizeDocument(source) {
    const items = Array.isArray(source.Items)
      ? source.Items
      : Array.isArray(source.items)
        ? source.items
        : [];

    return {
      PageNo: Number.isFinite(source.PageNo) ? source.PageNo : (Number.isFinite(source.pageNo) ? source.pageNo : 0),
      PageSize: Number.isFinite(source.PageSize) ? source.PageSize : (Number.isFinite(source.pageSize) ? source.pageSize : items.length),
      TotalCount: Number.isFinite(source.TotalCount) ? source.TotalCount : (Number.isFinite(source.totalCount) ? source.totalCount : items.length),
      PublisherUrl: source.PublisherUrl || source.publisherUrl || '',
      BlobPublicUrl: source.BlobPublicUrl || source.blobPublicUrl || '',
      Items: items.map((item) => this.normalizeItem(item))
    };
  }

  normalizeItem(item) {
    return {
      UrlPath: item?.UrlPath || item?.urlPath || '',
      Title: item?.Title || item?.title || '',
      Published: item?.Published || item?.published || null,
      Updated: item?.Updated || item?.updated || null,
      BannerImage: item?.BannerImage || item?.bannerImage || null,
      AuthorInfo: item?.AuthorInfo || item?.authorInfo || null,
      Content: item?.Content || item?.content || null,
      Introduction: item?.Introduction || item?.introduction || null
    };
  }

  isValid() {
    return (
      Number.isInteger(this.document.PageNo) &&
      Number.isInteger(this.document.PageSize) &&
      Number.isInteger(this.document.TotalCount) &&
      Array.isArray(this.document.Items)
    );
  }

  getMeta() {
    return {
      pageNo: this.document.PageNo,
      pageSize: this.document.PageSize,
      totalCount: this.document.TotalCount,
      publisherUrl: this.document.PublisherUrl,
      blobPublicUrl: this.document.BlobPublicUrl
    };
  }

  getItems() {
    return [...this.document.Items];
  }

  hasItems() {
    return this.document.Items.length > 0;
  }

  findByUrlPath(urlPath) {
    if (!urlPath) {
      return null;
    }

    const normalizedInput = this.normalizePath(urlPath);
    return this.document.Items.find((item) => this.normalizePath(item.UrlPath) === normalizedInput) || null;
  }

  filter(predicate) {
    if (typeof predicate !== 'function') {
      return this.getItems();
    }

    return this.document.Items.filter(predicate);
  }

  sortByPublishedDescending(items = this.document.Items) {
    return [...items].sort((a, b) => this.safeDateValue(b.Published) - this.safeDateValue(a.Published));
  }

  sortByUpdatedDescending(items = this.document.Items) {
    return [...items].sort((a, b) => this.safeDateValue(b.Updated) - this.safeDateValue(a.Updated));
  }

  sortByTitle(items = this.document.Items) {
    return [...items].sort((a, b) => (a.Title || '').localeCompare(b.Title || ''));
  }

  getPage(pageNo, pageSize = this.document.PageSize || 10) {
    const normalizedPageNo = Math.max(0, Number(pageNo) || 0);
    const normalizedPageSize = Math.max(1, Number(pageSize) || 10);
    const start = normalizedPageNo * normalizedPageSize;
    const end = start + normalizedPageSize;
    const items = this.document.Items.slice(start, end);

    return {
      pageNo: normalizedPageNo,
      pageSize: normalizedPageSize,
      totalCount: this.document.Items.length,
      items
    };
  }

  toJson(indented = false) {
    return JSON.stringify(this.document, null, indented ? 2 : 0);
  }

  buildPageUrl(item, useBlobPublicUrl = false, extension = '.html') {
    if (!item || !item.UrlPath) {
      return '';
    }

    const base = useBlobPublicUrl ? this.document.BlobPublicUrl : this.document.PublisherUrl;
    const normalizedBase = base ? base.replace(/\/+$/, '') : '';
    const normalizedPath = this.normalizePath(item.UrlPath).replace(/^\/+/, '');

    if (!normalizedBase) {
      return `/${normalizedPath}${extension || ''}`;
    }

    return `${normalizedBase}/${normalizedPath}${extension || ''}`;
  }

  normalizePath(path) {
    return String(path || '').trim().replace(/^\/+/, '').replace(/\/+$/, '').toLowerCase();
  }

  safeDateValue(value) {
    const date = new Date(value);
    const time = date.getTime();
    return Number.isFinite(time) ? time : 0;
  }
}

if (typeof window !== 'undefined') {
  window.TableOfContentsClient = TableOfContentsClient;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = TableOfContentsClient;
}
